using System.Globalization;
using System.Text.Json;
using Npgsql;
using Todir.Modules.Catalog.Contracts;
using Todir.Modules.Catalog.Domain;
using Todir.Platform.Messaging;
using Todir.Platform.Services;
using Todir.Platform.Transactions;
using Todir.SharedKernel.Identifiers;

namespace Todir.Modules.Catalog.Application;

public sealed class ProductService(ITransactionCoordinator coordinator, NpgsqlDataSource dataSource)
{
    public async Task<ProductDetails> CreateAsync(TenantId tenantId, Guid actorId, Guid membershipId, CreateProductRequest request, Guid correlationId, string? traceParent, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(request.DisplayName)) throw new CatalogException("catalog.name_required", "Product name is required.");
        var templateId = Guid.CreateVersion7(); var variantId = Guid.CreateVersion7(); var now = DateTimeOffset.UtcNow; var sku = Null(request.Sku); var normalizedSku = sku is null ? null : CatalogNormalization.Text(sku);
        await coordinator.ExecuteAsync(tenantId, async (context, token) =>
        {
            await EnsureUomAsync(context, tenantId, request.BaseUomId, token);
            await ExecuteAsync(context, "insert into foundation_catalog.product_template (tenant_id,id,display_name,display_name_normalized,name_ar,name_en,product_nature,category_id,brand_id,status,created_at,updated_at,version) values ($1,$2,$3,$4,$5,$6,$7,$8,$9,'Active',$10,$10,1)", token, tenantId.Value, templateId, request.DisplayName.Trim(), CatalogNormalization.Search(request.DisplayName), Null(request.NameAr) ?? (object)DBNull.Value, Null(request.NameEn) ?? (object)DBNull.Value, request.Nature.ToString(), (object?)request.CategoryId ?? DBNull.Value, (object?)request.BrandId ?? DBNull.Value, now);
            await ExecuteAsync(context, "insert into foundation_catalog.product_variant (tenant_id,id,product_template_id,sku,normalized_sku,is_default_variant,status,created_at,updated_at,version) values ($1,$2,$3,$4,$5,true,'Active',$6,$6,1)", token, tenantId.Value, variantId, templateId, sku is null ? DBNull.Value : sku, normalizedSku is null ? DBNull.Value : normalizedSku, now);
            await ExecuteAsync(context, "insert into foundation_catalog.product_uom (tenant_id,id,variant_id,uom_id,factor_to_base,is_base,effective_from,status,version) values ($1,$2,$3,$4,1,true,$5,'Active',1)", token, tenantId.Value, Guid.CreateVersion7(), variantId, request.BaseUomId, now);
            await ExecuteAsync(context, "insert into foundation_catalog.product_visibility (tenant_id,template_id,scope_type) values ($1,$2,'TenantWide')", token, tenantId.Value, templateId);
            await RefreshProjectionAsync(context, tenantId, templateId, variantId, token);
            await AuditAsync(context, tenantId, actorId, membershipId, templateId, "product_created", correlationId, now, new { request.DisplayName, request.Nature });
            context.AddOutbox(new OutboxMessage(Guid.CreateVersion7(), "CatalogProductCreatedV1", JsonSerializer.Serialize(new { templateId, variantId }), tenantId, now, correlationId, templateId, "catalog", traceParent));
            return true;
        }, ct);
        return await GetAsync(tenantId, templateId, ct) ?? throw new CatalogException("catalog.product_not_found", "Created product could not be read.");
    }

    public async Task<ProductDetails?> GetAsync(TenantId tenantId, Guid templateId, CancellationToken ct)
    {
        await using var connection = await dataSource.OpenConnectionAsync(ct); await SetTenantAsync(connection, tenantId, ct);
        const string sql = "select p.id,p.display_name,p.name_ar,p.name_en,p.product_nature,p.category_id,c.name,p.brand_id,b.name,p.status,p.created_at,p.updated_at,p.version,v.id,v.sku,u.code from foundation_catalog.product_template p left join foundation_catalog.product_category c on c.tenant_id=p.tenant_id and c.id=p.category_id left join foundation_catalog.brand b on b.tenant_id=p.tenant_id and b.id=p.brand_id join foundation_catalog.product_variant v on v.tenant_id=p.tenant_id and v.product_template_id=p.id and v.is_default_variant left join foundation_catalog.product_uom pu on pu.tenant_id=v.tenant_id and pu.variant_id=v.id and pu.is_base and pu.status='Active' and pu.effective_to is null left join foundation_catalog.uom u on u.tenant_id=pu.tenant_id and u.id=pu.uom_id where p.tenant_id=$1 and p.id=$2";
        await using var command = new NpgsqlCommand(sql, connection); command.Parameters.AddWithValue(tenantId.Value); command.Parameters.AddWithValue(templateId);
        await using var reader = await command.ExecuteReaderAsync(ct); if (!await reader.ReadAsync(ct)) return null;
        var details = new ProductDetails(reader.GetGuid(0), reader.GetGuid(13), reader.GetString(1), GetString(reader, 2), GetString(reader, 3), Enum.Parse<ProductNature>(reader.GetString(4)), GetString(reader, 14), GetString(reader, 15), GetGuid(reader, 5), GetString(reader, 6), GetGuid(reader, 7), GetString(reader, 8), Enum.Parse<CatalogStatus>(reader.GetString(9)), [], reader.GetFieldValue<DateTimeOffset>(10), reader.GetFieldValue<DateTimeOffset>(11), reader.GetInt64(12));
        await reader.DisposeAsync();
        var barcodes = new List<BarcodeDto>(); await using var barcode = new NpgsqlCommand("select id,variant_id,uom_id,barcode_type,value,is_primary from foundation_catalog.product_barcode where tenant_id=$1 and variant_id=$2 and status='Active' order by is_primary desc,value", connection); barcode.Parameters.AddWithValue(tenantId.Value); barcode.Parameters.AddWithValue(details.DefaultVariantId); await using var barcodeReader = await barcode.ExecuteReaderAsync(ct); while (await barcodeReader.ReadAsync(ct)) barcodes.Add(new BarcodeDto(barcodeReader.GetGuid(0), barcodeReader.GetGuid(1), GetGuid(barcodeReader, 2), barcodeReader.GetString(3), barcodeReader.GetString(4), barcodeReader.GetBoolean(5)));
        return details with { Barcodes = barcodes };
    }

    public async Task<PagedProducts> ListAsync(TenantId tenantId, string? search, ProductNature? nature, CatalogStatus? status, Guid? categoryId, Guid? brandId, int page, int pageSize, CancellationToken ct)
    {
        page = Math.Clamp(page, 1, 100000); pageSize = Math.Clamp(pageSize, 1, 100); var normalized = string.IsNullOrWhiteSpace(search) ? null : CatalogNormalization.Search(search);
        await using var connection = await dataSource.OpenConnectionAsync(ct); await SetTenantAsync(connection, tenantId, ct);
        const string where = "where tenant_id=$1 and ($2::text is null or display_name_normalized like '%' || $2 || '%' or lower(coalesce(name_ar,'')) like '%' || $2 || '%' or lower(coalesce(name_en,'')) like '%' || $2 || '%' or lower(coalesce(sku,'')) like '%' || $2 || '%' or lower(coalesce(category_name,'')) like '%' || $2 || '%' or exists(select 1 from foundation_catalog.product_barcode b where b.tenant_id=catalog_search_projection.tenant_id and b.variant_id=catalog_search_projection.variant_id and b.status='Active' and b.normalized_value like '%' || $2 || '%') or exists(select 1 from foundation_catalog.product_alias a where a.tenant_id=catalog_search_projection.tenant_id and a.variant_id=catalog_search_projection.variant_id and a.normalized_alias like '%' || $2 || '%')) and ($3::text is null or product_nature=$3) and ($4::text is null or status=$4) and ($5::uuid is null or category_id=$5) and ($6::uuid is null or exists(select 1 from foundation_catalog.product_template p_filter where p_filter.tenant_id=catalog_search_projection.tenant_id and p_filter.id=catalog_search_projection.template_id and p_filter.brand_id=$6) )";
        await using var count = new NpgsqlCommand($"select count(*) from foundation_catalog.catalog_search_projection {where}", connection); Add(count, tenantId.Value, normalized is null ? DBNull.Value : normalized, nature?.ToString() ?? (object)DBNull.Value, status?.ToString() ?? (object)DBNull.Value, categoryId ?? (object)DBNull.Value, brandId ?? (object)DBNull.Value); var total = Convert.ToInt32(await count.ExecuteScalarAsync(ct), CultureInfo.InvariantCulture);
        await using var command = new NpgsqlCommand($"select variant_id,template_id,display_name,name_ar,name_en,product_nature,sku,base_uom_code,category_name,(select b.name from foundation_catalog.brand b join foundation_catalog.product_template p_brand on p_brand.tenant_id=b.tenant_id and p_brand.brand_id=b.id where p_brand.tenant_id=catalog_search_projection.tenant_id and p_brand.id=catalog_search_projection.template_id),status,updated_at,(select version from foundation_catalog.product_template p where p.tenant_id=$1 and p.id=template_id) from foundation_catalog.catalog_search_projection {where} order by updated_at desc,variant_id limit $7 offset $8", connection); Add(command, tenantId.Value, normalized is null ? DBNull.Value : normalized, nature?.ToString() ?? (object)DBNull.Value, status?.ToString() ?? (object)DBNull.Value, categoryId ?? (object)DBNull.Value, brandId ?? (object)DBNull.Value, pageSize, (page - 1) * pageSize);
        var items = new List<ProductSummary>(); await using var reader = await command.ExecuteReaderAsync(ct); while (await reader.ReadAsync(ct)) items.Add(new ProductSummary(reader.GetGuid(1), reader.GetGuid(0), reader.GetString(2), GetString(reader, 3), GetString(reader, 4), Enum.Parse<ProductNature>(reader.GetString(5)), GetString(reader, 6), GetString(reader, 7), GetString(reader, 8), GetString(reader, 9), Enum.Parse<CatalogStatus>(reader.GetString(10)), reader.GetFieldValue<DateTimeOffset>(11), reader.IsDBNull(12) ? 1 : reader.GetInt64(12)));
        return new PagedProducts(items, total, page, pageSize);
    }

    public async Task<ProductDetails> UpdateAsync(TenantId tenantId, Guid actorId, Guid membershipId, Guid id, UpdateProductRequest request, Guid correlationId, string? traceParent, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(request.DisplayName)) throw new CatalogException("catalog.name_required", "Product name is required."); var normalizedSku = string.IsNullOrWhiteSpace(request.Sku) ? null : CatalogNormalization.Text(request.Sku);
        await coordinator.ExecuteAsync(tenantId, async (context, token) => { var changed = await ExecuteAsync(context, "update foundation_catalog.product_template set display_name=$3,display_name_normalized=$4,name_ar=$5,name_en=$6,category_id=$7,brand_id=$8,updated_at=$9,version=version+1 where tenant_id=$1 and id=$2 and version=$10 and status='Active'", token, tenantId.Value, id, request.DisplayName.Trim(), CatalogNormalization.Search(request.DisplayName), Null(request.NameAr) ?? (object)DBNull.Value, Null(request.NameEn) ?? (object)DBNull.Value, request.CategoryId ?? (object)DBNull.Value, request.BrandId ?? (object)DBNull.Value, DateTimeOffset.UtcNow, request.Version); if (changed == 0) throw new CatalogException("catalog.concurrency_conflict", "The product was changed by another request or is archived."); var updated = await ExecuteAsync(context, "update foundation_catalog.product_variant set sku=$3,normalized_sku=$4,updated_at=$5,version=version+1 where tenant_id=$1 and product_template_id=$2 and is_default_variant", token, tenantId.Value, id, Null(request.Sku) ?? (object)DBNull.Value, normalizedSku ?? (object)DBNull.Value, DateTimeOffset.UtcNow); if (updated == 0) throw new CatalogException("catalog.variant_not_found", "Default variant was not found."); var variantId = await ScalarAsync<Guid>(context, "select id from foundation_catalog.product_variant where tenant_id=$1 and product_template_id=$2 and is_default_variant", token, tenantId.Value, id); await RefreshProjectionAsync(context, tenantId, id, variantId, token); await AuditAsync(context, tenantId, actorId, membershipId, id, "product_identity_changed", correlationId, DateTimeOffset.UtcNow, new { request.DisplayName }); context.AddOutbox(new OutboxMessage(Guid.CreateVersion7(), "CatalogProductChangedV1", JsonSerializer.Serialize(new { templateId = id, variantId }), tenantId, DateTimeOffset.UtcNow, correlationId, id, "catalog", traceParent)); return true; }, ct);
        return await GetAsync(tenantId, id, ct) ?? throw new CatalogException("catalog.product_not_found", "Product was not found.");
    }

    public async Task<ProductDetails> ChangeStatusAsync(TenantId tenantId, Guid actorId, Guid membershipId, Guid id, bool restore, long version, Guid correlationId, string? traceParent, CancellationToken ct)
    {
        var status = restore ? CatalogStatus.Active : CatalogStatus.Archived; await coordinator.ExecuteAsync(tenantId, async (context, token) => { var changed = await ExecuteAsync(context, "update foundation_catalog.product_template set status=$3,updated_at=$4,version=version+1 where tenant_id=$1 and id=$2 and version=$5", token, tenantId.Value, id, status.ToString(), DateTimeOffset.UtcNow, version); if (changed == 0) throw new CatalogException("catalog.concurrency_conflict", "The product state changed or it was not found."); await ExecuteAsync(context, "update foundation_catalog.product_variant set status=$3,updated_at=$4,version=version+1 where tenant_id=$1 and product_template_id=$2", token, tenantId.Value, id, status.ToString(), DateTimeOffset.UtcNow); var variantId = await ScalarAsync<Guid>(context, "select id from foundation_catalog.product_variant where tenant_id=$1 and product_template_id=$2 and is_default_variant", token, tenantId.Value, id); await RefreshProjectionAsync(context, tenantId, id, variantId, token); await AuditAsync(context, tenantId, actorId, membershipId, id, restore ? "product_restored" : "product_archived", correlationId, DateTimeOffset.UtcNow, new { status }); context.AddOutbox(new OutboxMessage(Guid.CreateVersion7(), restore ? "CatalogProductRestoredV1" : "CatalogProductArchivedV1", JsonSerializer.Serialize(new { templateId = id, variantId }), tenantId, DateTimeOffset.UtcNow, correlationId, id, "catalog", traceParent)); return true; }, ct); return await GetAsync(tenantId, id, ct) ?? throw new CatalogException("catalog.product_not_found", "Product was not found.");
    }

    public async Task<BarcodeDto> AddBarcodeAsync(TenantId tenantId, Guid actorId, Guid membershipId, Guid templateId, Guid? requestedVariantId, AddBarcodeRequest request, Guid correlationId, CancellationToken ct)
    {
        var value = IdentifierRules.RequireBarcode(request.Value); return await coordinator.ExecuteAsync(tenantId, async (context, token) => { var variantId = requestedVariantId ?? await ScalarAsync<Guid>(context, "select id from foundation_catalog.product_variant where tenant_id=$1 and product_template_id=$2 and is_default_variant and status='Active'", token, tenantId.Value, templateId); var validVariant = await ScalarNullableGuidAsync(context, "select id from foundation_catalog.product_variant where tenant_id=$1 and id=$2 and product_template_id=$3 and status='Active'", token, tenantId.Value, variantId, templateId); if (validVariant is null) throw new CatalogException("catalog.variant_not_found", "Variant was not found for this product."); if (request.UomId is not null && await ScalarNullableGuidAsync(context, "select id from foundation_catalog.product_uom where tenant_id=$1 and variant_id=$2 and uom_id=$3 and status='Active'", token, tenantId.Value, variantId, request.UomId.Value) is null) throw new CatalogException("catalog.uom_not_found", "The barcode unit is not assigned to this variant."); var id = Guid.CreateVersion7(); try { await ExecuteAsync(context, "insert into foundation_catalog.product_barcode (tenant_id,id,variant_id,uom_id,barcode_type,value,normalized_value,is_primary,status,created_at) values ($1,$2,$3,$4,$5,$6,$7,$8,'Active',$9)", token, tenantId.Value, id, variantId, request.UomId ?? (object)DBNull.Value, request.BarcodeType.ToString(), request.Value.Trim(), value, request.IsPrimary, DateTimeOffset.UtcNow); } catch (PostgresException ex) when (ex.SqlState == "23505") { throw new CatalogException("catalog.barcode_duplicate", "Barcode already belongs to another product."); } await AuditAsync(context, tenantId, actorId, membershipId, templateId, "product_barcode_added", correlationId, DateTimeOffset.UtcNow, new { request.Value, variantId }); return new BarcodeDto(id, variantId, request.UomId, request.BarcodeType.ToString(), request.Value.Trim(), request.IsPrimary); }, ct);
    }

    private static async Task EnsureUomAsync(ITransactionContext context, TenantId tenantId, Guid uomId, CancellationToken ct) { if (await ScalarNullableGuidAsync(context, "select id from foundation_catalog.uom where tenant_id=$1 and id=$2 and status='Active'", ct, tenantId.Value, uomId) is null) throw new CatalogException("catalog.uom_not_found", "Base unit was not found."); }
    private static async Task RefreshProjectionAsync(ITransactionContext context, TenantId tenantId, Guid templateId, Guid variantId, CancellationToken ct) { await ExecuteAsync(context, "delete from foundation_catalog.catalog_search_projection where tenant_id=$1 and variant_id=$2", ct, tenantId.Value, variantId); await ExecuteAsync(context, "insert into foundation_catalog.catalog_search_projection (tenant_id,variant_id,template_id,display_name,display_name_normalized,name_ar,name_en,sku,normalized_sku,category_id,category_name,base_uom_code,product_nature,status,updated_at) select p.tenant_id,v.id,p.id,p.display_name,p.display_name_normalized,p.name_ar,p.name_en,v.sku,v.normalized_sku,p.category_id,c.name,u.code,p.product_nature,p.status,p.updated_at from foundation_catalog.product_template p join foundation_catalog.product_variant v on v.tenant_id=p.tenant_id and v.product_template_id=p.id left join foundation_catalog.product_category c on c.tenant_id=p.tenant_id and c.id=p.category_id left join foundation_catalog.product_uom pu on pu.tenant_id=v.tenant_id and pu.variant_id=v.id and pu.is_base and pu.status='Active' and pu.effective_to is null left join foundation_catalog.uom u on u.tenant_id=pu.tenant_id and u.id=pu.uom_id where p.tenant_id=$1 and p.id=$2 and v.id=$3", ct, tenantId.Value, templateId, variantId); }
    private static async Task AuditAsync(ITransactionContext context, TenantId tenantId, Guid actorId, Guid membershipId, Guid entityId, string action, Guid correlationId, DateTimeOffset now, object after) => await NpgsqlAuditWriter.WriteAsync(context.Connection, context.Transaction, new AuditEntry(Guid.CreateVersion7(), tenantId, null, null, "User", actorId, membershipId, "catalog", action, "product", entityId, null, JsonSerializer.Serialize(after), null, "api", correlationId, System.Diagnostics.Activity.Current?.Id, now, null));
    private static async Task SetTenantAsync(NpgsqlConnection connection, TenantId tenantId, CancellationToken ct) { await using var command = new NpgsqlCommand("select set_config('app.tenant_id',$1,false)", connection); command.Parameters.AddWithValue(tenantId.Value.ToString("D")); await command.ExecuteNonQueryAsync(ct); }
    private static async Task<int> ExecuteAsync(ITransactionContext context, string sql, CancellationToken ct, params object[] values) { await using var command = new NpgsqlCommand(sql, context.Connection, context.Transaction); Add(command, values); return await command.ExecuteNonQueryAsync(ct); }
    private static async Task<T> ScalarAsync<T>(ITransactionContext context, string sql, CancellationToken ct, params object[] values) { await using var command = new NpgsqlCommand(sql, context.Connection, context.Transaction); Add(command, values); var value = await command.ExecuteScalarAsync(ct); if (value is null or DBNull) throw new KeyNotFoundException("catalog.not_found"); if (value is T result) return result; if (typeof(T) == typeof(Guid)) return (T)(object)Guid.Parse(Convert.ToString(value, CultureInfo.InvariantCulture)!); return (T)Convert.ChangeType(value, Nullable.GetUnderlyingType(typeof(T)) ?? typeof(T), CultureInfo.InvariantCulture); }
    private static async Task<Guid?> ScalarNullableGuidAsync(ITransactionContext context, string sql, CancellationToken ct, params object[] values) { await using var command = new NpgsqlCommand(sql, context.Connection, context.Transaction); Add(command, values); var value = await command.ExecuteScalarAsync(ct); return value is null or DBNull ? null : (Guid)value; }
    private static void Add(NpgsqlCommand command, params object[] values) { for (var i = 0; i < values.Length; i++) command.Parameters.AddWithValue(values[i] ?? DBNull.Value); }
    private static string? Null(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim();
    private static string? GetString(NpgsqlDataReader reader, int index) => reader.IsDBNull(index) ? null : reader.GetString(index);
    private static Guid? GetGuid(NpgsqlDataReader reader, int index) => reader.IsDBNull(index) ? null : reader.GetGuid(index);
}

public sealed class CatalogMasterDataService(ITransactionCoordinator coordinator, NpgsqlDataSource dataSource)
{
    public async Task<CategoryDto> CreateCategoryAsync(TenantId tenantId, CreateCategoryRequest request, CancellationToken ct) { if (string.IsNullOrWhiteSpace(request.Name)) throw new CatalogException("catalog.category_name_required", "Category name is required."); var id = Guid.CreateVersion7(); await coordinator.ExecuteAsync(tenantId, async (context, token) => { if (request.ParentId is not null && await ScalarAsync(context, "select id from foundation_catalog.product_category where tenant_id=$1 and id=$2 and status='Active'", token, tenantId.Value, request.ParentId.Value) is null) throw new CatalogException("catalog.parent_not_found", "Parent category was not found."); await ExecuteAsync(context, "insert into foundation_catalog.product_category (tenant_id,id,name,name_normalized,parent_id,status,created_at,updated_at,version) values ($1,$2,$3,$4,$5,'Active',$6,$6,1)", token, tenantId.Value, id, request.Name.Trim(), CatalogNormalization.Search(request.Name), request.ParentId ?? (object)DBNull.Value, DateTimeOffset.UtcNow); return true; }, ct); return new CategoryDto(id, request.Name.Trim(), request.ParentId, CatalogStatus.Active, 1); }
    public async Task<IReadOnlyList<CategoryDto>> ListCategoriesAsync(TenantId tenantId, CancellationToken ct) { await using var connection = await dataSource.OpenConnectionAsync(ct); await SetTenantAsync(connection, tenantId, ct); await using var command = new NpgsqlCommand("select id,name,parent_id,status,version from foundation_catalog.product_category where tenant_id=$1 order by name", connection); command.Parameters.AddWithValue(tenantId.Value); var result = new List<CategoryDto>(); await using var reader = await command.ExecuteReaderAsync(ct); while (await reader.ReadAsync(ct)) result.Add(new CategoryDto(reader.GetGuid(0), reader.GetString(1), GetGuid(reader, 2), Enum.Parse<CatalogStatus>(reader.GetString(3)), reader.GetInt64(4))); return result; }
    public async Task<BrandDto> CreateBrandAsync(TenantId tenantId, CreateBrandRequest request, CancellationToken ct) { if (string.IsNullOrWhiteSpace(request.Name)) throw new CatalogException("catalog.brand_name_required", "Brand name is required."); var id = Guid.CreateVersion7(); await coordinator.ExecuteAsync(tenantId, async (context, token) => { await ExecuteAsync(context, "insert into foundation_catalog.brand (tenant_id,id,name,name_normalized,status,created_at,updated_at,version) values ($1,$2,$3,$4,'Active',$5,$5,1)", token, tenantId.Value, id, request.Name.Trim(), CatalogNormalization.Search(request.Name), DateTimeOffset.UtcNow); return true; }, ct); return new BrandDto(id, request.Name.Trim(), CatalogStatus.Active, 1); }
    public async Task<IReadOnlyList<BrandDto>> ListBrandsAsync(TenantId tenantId, CancellationToken ct) { await using var connection = await dataSource.OpenConnectionAsync(ct); await SetTenantAsync(connection, tenantId, ct); await using var command = new NpgsqlCommand("select id,name,status,version from foundation_catalog.brand where tenant_id=$1 order by name", connection); command.Parameters.AddWithValue(tenantId.Value); var result = new List<BrandDto>(); await using var reader = await command.ExecuteReaderAsync(ct); while (await reader.ReadAsync(ct)) result.Add(new BrandDto(reader.GetGuid(0), reader.GetString(1), Enum.Parse<CatalogStatus>(reader.GetString(2)), reader.GetInt64(3))); return result; }
    public async Task<UomDto> CreateUomAsync(TenantId tenantId, CreateUomRequest request, CancellationToken ct) { if (string.IsNullOrWhiteSpace(request.Code) || string.IsNullOrWhiteSpace(request.NameEn)) throw new CatalogException("catalog.uom_required", "Unit code and English name are required."); var id = Guid.CreateVersion7(); await coordinator.ExecuteAsync(tenantId, async (context, token) => { await ExecuteAsync(context, "insert into foundation_catalog.uom (tenant_id,id,code,name_ar,name_en,dimension,allow_fraction,precision,status,created_at,updated_at,version) values ($1,$2,$3,$4,$5,$6,$7,$8,'Active',$9,$9,1)", token, tenantId.Value, id, CatalogNormalization.Text(request.Code), request.NameAr.Trim(), request.NameEn.Trim(), request.Dimension.ToString(), request.AllowFraction, request.Precision, DateTimeOffset.UtcNow); return true; }, ct); return new UomDto(id, CatalogNormalization.Text(request.Code), request.NameAr.Trim(), request.NameEn.Trim(), request.Dimension, request.AllowFraction, request.Precision, CatalogStatus.Active); }
    public async Task<IReadOnlyList<UomDto>> ListUomsAsync(TenantId tenantId, CancellationToken ct) { await using var connection = await dataSource.OpenConnectionAsync(ct); await SetTenantAsync(connection, tenantId, ct); await using var command = new NpgsqlCommand("select id,code,name_ar,name_en,dimension,allow_fraction,precision,status from foundation_catalog.uom where tenant_id=$1 and status='Active' order by code", connection); command.Parameters.AddWithValue(tenantId.Value); var result = new List<UomDto>(); await using var reader = await command.ExecuteReaderAsync(ct); while (await reader.ReadAsync(ct)) result.Add(new UomDto(reader.GetGuid(0),reader.GetString(1),reader.GetString(2),reader.GetString(3),Enum.Parse<UomDimension>(reader.GetString(4)),reader.GetBoolean(5),reader.GetInt16(6),Enum.Parse<CatalogStatus>(reader.GetString(7)))); return result; }
    private static async Task SetTenantAsync(NpgsqlConnection connection, TenantId tenantId, CancellationToken ct) { await using var command = new NpgsqlCommand("select set_config('app.tenant_id',$1,false)", connection); command.Parameters.AddWithValue(tenantId.Value.ToString("D")); await command.ExecuteNonQueryAsync(ct); }
    private static async Task<int> ExecuteAsync(ITransactionContext context, string sql, CancellationToken ct, params object[] values) { await using var command = new NpgsqlCommand(sql, context.Connection, context.Transaction); for (var i=0;i<values.Length;i++) command.Parameters.AddWithValue(values[i] ?? DBNull.Value); return await command.ExecuteNonQueryAsync(ct); }
    private static async Task<Guid?> ScalarAsync(ITransactionContext context,string sql,CancellationToken ct,params object[] values){await using var command=new NpgsqlCommand(sql,context.Connection,context.Transaction);for(var i=0;i<values.Length;i++)command.Parameters.AddWithValue(values[i]??DBNull.Value);var value=await command.ExecuteScalarAsync(ct);return value is null or DBNull?null:(Guid)value;}
    private static Guid? GetGuid(NpgsqlDataReader reader,int index)=>reader.IsDBNull(index)?null:reader.GetGuid(index);
}
